function futureValue(monthly, annualRate, months){
  var r=annualRate/12;
  if(r===0) return monthly*months;
  return monthly*((Math.pow(1+r,months)-1)/r);
}
function monthsToGoal(goal, monthly, annualRate){
  var r=annualRate/12;
  if(r===0){ if(monthly<=0) return null; return goal/monthly; }
  if(monthly<=0) return null;
  var base=1+goal*r/monthly; if(base<=0) return null;
  return Math.log(base)/Math.log(1+r);
}
function totalInterest(goal,monthly,annualRate){var n=monthsToGoal(goal,monthly,annualRate);var fv=futureValue(monthly,annualRate,n);return fv-goal;}
var EXPORTS={futureValue:futureValue,monthsToGoal:monthsToGoal,totalInterest:totalInterest};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
